begin;
select no_plan();
create temp table access_actors(name text primary key,owner_id uuid,workspace_id uuid,client_user_id uuid,client_id uuid,template_id uuid);
grant select on access_actors to authenticated;
create function pg_temp.access_fixture(p_name text) returns void language plpgsql as $$
declare o uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); a uuid; w uuid; c uuid; t uuid; staff uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(o,o::text||'@access.test'),(u,u::text||'@access.test');
 insert into public.pt_profiles(user_id,full_name) values(o,'Access coach');
 a:=public.ensure_commercial_billing_account(o,'manual');
 insert into public.account_subscriptions(billing_account_id,plan_version_id,subscription_kind,status,source) select a,id,'complimentary','active','legacy_beta_backfill' from public.commercial_plan_versions where plan_key='scale' and status='active';
 insert into public.workspaces(name,owner_user_id) values('Access workspace',o) returning id into w;
 insert into public.clients(workspace_id,user_id,display_name,status) values(w,u,'Existing client','active') returning id into c;
 insert into public.workout_templates(workspace_id,name) values(w,'Existing template') returning id into t;
 insert into public.pt_hub_profiles(user_id,slug,is_published,marketplace_visible) values(o,'access-'||substr(o::text,1,8),true,true);
 insert into public.pt_hub_settings(user_id,profile_visibility) values(o,'listed');
 insert into auth.users(id,email) values(staff,staff::text||'@access.test');
 insert into public.workspace_members(workspace_id,user_id,role,status) values(w,staff,'assistant_coach','active');
 insert into public.workspace_member_invites(workspace_id,email,role,client_access_mode,token_hash,status,invited_by_user_id,expires_at) values(w,'pending-'||staff::text||'@access.test','assistant_coach','assigned_clients_only',md5(staff::text)||md5(w::text),'pending',o,now()+interval '1 day');
 insert into public.pt_packages(pt_user_id,title,status,is_public) values(o,'Access package','active',true);
 insert into public.invites(workspace_id,code,token,created_by_user_id,expires_at) values(w,'access-'||p_name,'access-token-'||p_name,o,now()+interval '1 day');
 insert into access_actors values(p_name,o,w,u,c,t);
end $$;
select pg_temp.access_fixture('full');
select pg_temp.access_fixture('grace');
select pg_temp.access_fixture('restricted');
select pg_temp.access_fixture('expired');
-- Real delivery parents exercise indirect scopes and normalization ordering.
do $$ declare x record; t uuid; begin
 for x in select * from access_actors loop
  perform set_config('request.jwt.claim.sub',x.owner_id::text,true);
  insert into public.assigned_workouts(client_id,workout_template_id,scheduled_date) values(x.client_id,x.template_id,current_date);
  insert into public.conversations(workspace_id,client_id) values(x.workspace_id,x.client_id) on conflict do nothing;
  insert into public.checkin_templates(workspace_id,name) values(x.workspace_id,'Access check-in') returning id into t;
  update public.clients set checkin_template_id=t,checkin_start_date=public.normalize_checkin_due_date(current_date-7),checkin_frequency='weekly' where id=x.client_id;
  insert into public.checkin_photos(checkin_id,client_id,photo_type,url,storage_path) select ci.id,ci.client_id,p.kind,'https://example.invalid/fixture','fixture/'||p.kind from public.checkins ci cross join (values('front'),('side'),('back')) p(kind) where ci.client_id=x.client_id and ci.week_ending_saturday<=current_date;
 end loop;
 perform set_config('request.jwt.claim.sub','',true);
end $$;
insert into public.workspaces(name,owner_user_id) select 'Empty access closure',owner_id from access_actors where name='expired';
insert into public.workout_templates(workspace_id,name) select id,'Unassigned close fixture' from public.workspaces where name='Empty access closure';
update public.account_subscriptions s set status=x.name, restricted_at=case when x.name='restricted' then now() end, expired_at=case when x.name='expired' then now() end from public.billing_accounts a join access_actors x on x.owner_id=a.owner_user_id where s.billing_account_id=a.id and x.name<>'full';
select is(public.is_commercial_action_allowed('onboarding','billing_manage'),true,'onboarding: billing_manage');
select is(public.is_commercial_action_allowed('onboarding','account_security'),true,'onboarding: account_security');
