select throws_ok($$select public.is_commercial_action_allowed('full','unknown')$$,'22023','ACCOUNT_ACCESS_ACTION_NOT_ALLOWED','unknown action rejected');
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='full'),true);
set local role authenticated;
select is(public.get_my_commercial_access_summary()->>'accessMode','full','full canonical owner mode');
select is((select public.get_workspace_commercial_access(workspace_id)->>'accessMode' from access_actors where name='full'),'full','full workspace owner mode');
select lives_ok($$update public.workout_templates set name='Delivery edited' where id=(select template_id from access_actors where name='full')$$,'full existing delivery allowed');
select lives_ok($$update public.workspaces set name='Business edited' where id=(select workspace_id from access_actors where name='full')$$,'full business configuration allowed');
reset role;
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='full'),true);
set local role authenticated;
select lives_ok($$select public.update_workspace_team_member_status(x.workspace_id,m.id,'suspended') from access_actors x join public.workspace_members m on m.workspace_id=x.workspace_id where x.name='full' and m.user_id<>x.owner_id$$,'full: member suspension remains available');
select lives_ok($$select public.revoke_workspace_team_invite(x.workspace_id,i.id) from access_actors x join public.workspace_member_invites i on i.workspace_id=x.workspace_id where x.name='full'$$,'full: invite revocation remains available');
select lives_ok($$select public.update_my_pt_package(p.id,'{"status":"archived","is_public":false}') from public.pt_packages p join access_actors x on x.owner_id=p.pt_user_id where x.name='full'$$,'full: package archival remains available');
reset role;
select set_config('request.jwt.claim.sub',(select client_user_id::text from access_actors where name='full'),true);
set local role authenticated;
select lives_ok($$select public.accept_invite(p_token=>'access-token-full')$$,'full: token invite consumption remains authorized');
select lives_ok($$insert into public.habit_logs(client_id,log_date,steps) select client_id,current_date,100 from access_actors where name='full'$$,'full client habit submission allowed');
select lives_ok($$insert into public.workout_sessions(assigned_workout_id) select w.id from public.assigned_workouts w join access_actors x on x.client_id=w.client_id where x.name='full'$$,'full: workout session resolves assigned parent before normalization');
select lives_ok($$update public.checkins set submitted_at=now() where id=(select ci.id from public.checkins ci join access_actors x on x.client_id=ci.client_id where x.name='full' order by ci.week_ending_saturday limit 1)$$,'full: complete check-in submission');
