select is((select count(*)::integer from public.pt_hub_profiles where user_id in (select owner_id from access_actors) and is_published),4,'access loss preserves all publication preferences');
select is((select count(*)::integer from public.pt_hub_profiles where user_id in (select owner_id from access_actors) and public.is_coach_accepting_applications(user_id)),1,'only full owner accepts applications');
select ok(not has_function_privilege('authenticated','public.resolve_account_commercial_access(uuid)','execute'),'private resolver cannot select foreign owner');
select ok(not has_function_privilege('authenticated','public.assert_commercial_action_allowed(uuid,text,uuid,uuid)','execute'),'private assertion cannot become authorization bypass');

-- Resolve each shared workspace independently of the caller's personal plan.
insert into public.workspace_members(workspace_id,user_id,role,status) select f.workspace_id,e.owner_id,'admin','active' from access_actors f cross join access_actors e where f.name='full' and e.name='expired';
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='expired'),true);
set local role authenticated;
select is((select public.get_workspace_commercial_access(workspace_id)->>'accessMode' from access_actors where name='full'),'full','expired personal owner accesses full shared workspace');
select ok((select not (public.get_workspace_commercial_access(workspace_id) ?| array['price','limits','planKey','providerSubscriptionId','reason']) from access_actors where name='full'),'shared summary omits billing details');
select lives_ok($$update public.workout_templates set name='Shared delivery' where id=(select template_id from access_actors where name='full')$$,'shared owner state authorizes delivery');
select lives_ok($$select public.pt_archive_client_relationship(client_id) from access_actors where name='expired'$$,'expired owner may explicitly remove client relationship');
reset role;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='full'),true);
set local role authenticated;
select lives_ok($$select public.send_conversation_message(c.id,x.owner_id,'pt','Coach','Existing relationship message',false) from public.conversations c join access_actors x on x.client_id=c.client_id where x.name='full'$$,'full coach message allowed');
reset role;
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='grace'),true);
set local role authenticated;
select lives_ok($$select public.send_conversation_message(c.id,x.owner_id,'pt','Coach','Existing relationship message',false) from public.conversations c join access_actors x on x.client_id=c.client_id where x.name='grace'$$,'grace coach message allowed');
reset role;
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='restricted'),true);
set local role authenticated;
select throws_ok($$select public.send_conversation_message(c.id,x.owner_id,'pt','Coach','Existing relationship message',false) from public.conversations c join access_actors x on x.client_id=c.client_id where x.name='restricted'$$,'42501','ACCOUNT_ACCESS_READ_ONLY','restricted coach message denied');
reset role;
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='expired'),true);
set local role authenticated;
reset role;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='expired'),true);
set local role authenticated;
select throws_ok($$delete from public.workspaces where id=(select workspace_id from access_actors where name='expired')$$,'P0001','This template is already assigned to a client and cannot be deleted. Existing client assignments prevent deletion. Historical records are preserved.','existing assigned-history deletion protection is preserved');
select lives_ok($$delete from public.workspaces where name='Empty access closure'$$,'expired owner can close eligible workspace through guarded FK cascades');
reset role;
select set_config('request.jwt.claim.sub','',true);

create temp table access_bootstrap(name text,id uuid default gen_random_uuid());
grant select on access_bootstrap to authenticated;
insert into access_bootstrap(name) values('onboarding'),('inconsistent');
insert into auth.users(id,email) select id,id::text||'@access.test' from access_bootstrap;
insert into public.pt_profiles(user_id,full_name) select id,'Bootstrap access' from access_bootstrap;
-- Deliberate, transaction-local legacy-corruption fixture; runtime roles cannot
-- disable these triggers. Restore both before invoking authenticated behavior.
alter table public.workspaces disable trigger workspace_account_trial;
alter table public.workspaces disable trigger zz_capacity_admission;
insert into public.workspaces(name,owner_user_id) select 'Legacy missing subscription',id from access_bootstrap where name='inconsistent';
alter table public.workspaces enable trigger workspace_account_trial;
alter table public.workspaces enable trigger zz_capacity_admission;
select set_config('request.jwt.claim.sub',(select id::text from access_bootstrap where name='onboarding'),true);
set local role authenticated;
select is(public.get_my_commercial_access_summary()->>'accessMode','onboarding','no subscription and no workspace means onboarding');
select lives_ok($$select public.create_workspace('First access workspace')$$,'onboarding permits first workspace through original bootstrap');
select is(public.get_my_commercial_access_summary()->>'accessMode','full','first workspace starts canonical trial');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from access_bootstrap where name='inconsistent'),true);
set local role authenticated;
select is(public.get_my_commercial_access_summary()->>'reason','owner_recovery_required','existing workspace with missing subscription has distinct diagnostic');
select is(public.get_my_commercial_access_summary()->>'accessMode','read_only','inconsistent legacy owner fails closed without deleting data');
select throws_ok($$select public.create_workspace('Do not restart trial')$$,'42501','ACCOUNT_ACCESS_OWNER_RECOVERY_REQUIRED','missing history cannot bootstrap another workspace');
reset role;
select set_config('request.jwt.claim.sub','',true);

-- The same client user can retain an unavailable historical relationship and
-- interact independently with another full coach.
insert into public.clients(workspace_id,user_id,status,display_name) select f.workspace_id,e.client_user_id,'active','Second coaching relationship' from access_actors f cross join access_actors e where f.name='full' and e.name='expired';
select set_config('request.jwt.claim.sub',(select client_user_id::text from access_actors where name='expired'),true);
set local role authenticated;
select is((select public.get_client_coaching_access(c.id)->>'serviceMode' from public.clients c join access_actors f on f.workspace_id=c.workspace_id where f.name='full' and c.user_id=auth.uid()),'interactive','another full coaching relationship remains interactive');
select is((select public.get_client_coaching_access(client_id)->>'serviceMode' from access_actors where name='expired'),'unavailable','expired historical relationship remains independently unavailable');
select ok((select public.commercial_storage_write_allowed('medical_documents',client_id::text||'/personal.pdf') from access_actors where name='expired'),'client personal medical upload remains independent');
select ok((select not public.commercial_storage_write_allowed('checkin-photos',client_id::text||'/front.png') from access_actors where name='expired'),'expired coached photo upload is denied');
reset role;
select set_config('request.jwt.claim.sub',(select owner_id::text from access_actors where name='grace'),true);
set local role authenticated;
select ok((select not public.commercial_storage_write_allowed('workspace_branding',workspace_id::text||'/logo.png') from access_actors where name='grace'),'grace denies branding upload');
select ok((select public.commercial_storage_write_allowed('checkin-photos',client_id::text||'/front.png') from access_actors where name='grace'),'grace retains authorized existing delivery uploads');
reset role;
select set_config('request.jwt.claim.sub','',true);
select is((select count(*)::integer from pg_policies where schemaname='storage' and policyname in ('commercial_storage_insert','commercial_storage_update') and permissive='RESTRICTIVE'),2,'storage checks cannot be bypassed by a permissive policy');

update public.workspace_members set role='pt_coach' where workspace_id=(select workspace_id from access_actors where name='grace') and role='assistant_coach';
select set_config('request.jwt.claim.sub',(select m.user_id::text from public.workspace_members m join access_actors x on x.workspace_id=m.workspace_id where x.name='grace' and m.role='pt_coach'),true);
set local role authenticated;
select lives_ok($$select public.set_my_appearance_preferences('dark',true)$$,'personal appearance remains available on suspended legacy membership');
reset role;
select set_config('request.jwt.claim.sub','',true);
select * from finish();
rollback;
